import{_ as t,o as a,c as n,a0 as d}from"./chunks/framework.ovZk0eWp.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"Architecture.md","filePath":"Architecture.md"}'),r={name:"Architecture.md"};function s(o,e,i,c,p,l){return a(),n("div",null,[...e[0]||(e[0]=[d(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><hr><h2 id="what-each-layer-owns" tabindex="-1">What each layer owns <a class="header-anchor" href="#what-each-layer-owns" aria-label="Permalink to &quot;What each layer owns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Owns</th></tr></thead><tbody><tr><td><code>.me</code></td><td>Seed derivation, semantic tree, reactivity, memory</td></tr><tr><td><code>cleaker</code></td><td>Namespace binding, surface fallback, triad verification</td></tr><tr><td><code>monad.ai</code></td><td>HTTP surface, kernel exposure, mesh announce/discover</td></tr><tr><td><code>netget</code></td><td>Physical routing, domain → port mapping, SSL, monad placement</td></tr></tbody></table><hr><h2 id="the-node" tabindex="-1">The node <a class="header-anchor" href="#the-node" aria-label="Permalink to &quot;The node&quot;">​</a></h2><p>A node is <em>a machine running netget.</em> It is the physical boundary of the stack:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hostname.local ← node hostname</span></span>
<span class="line"><span>  port 80/443 → netget ← entry point</span></span>
<span class="line"><span>  port 8161 → monad ← suign.cleaker.me kernel</span></span>
<span class="line"><span>  port 3000 → any service  ← additional processes</span></span>
<span class="line"><span>  ~/.get/html/ → landing page ← node identity page</span></span></code></pre></div><p>When you visit <code>hostname.local</code>, you reach the node&#39;s gateway. NetGet reads <code>~/.get/runtime/domain-map.json</code> and routes the request to the correct destination.</p><hr><h2 id="hot-reload-architecture" tabindex="-1">Hot-reload architecture <a class="header-anchor" href="#hot-reload-architecture" aria-label="Permalink to &quot;Hot-reload architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.get/runtime/domain-map.json    ← written by netget CLI / generate-domain-map</span></span>
<span class="line"><span>~/.get/runtime/domain-map.version ← bumped on every write</span></span>
<span class="line"><span></span></span>
<span class="line"><span>OpenResty Lua timer (1s):</span></span>
<span class="line"><span>  read version → if changed → reload domain-map → update _G.DOMAIN_MAP</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Result: routing changes take effect in under 1 second, no nginx restart needed.</span></span></code></pre></div><hr><h2 id="nrp-integration-2026-05-08" tabindex="-1">NRP integration (2026-05-08) <a class="header-anchor" href="#nrp-integration-2026-05-08" aria-label="Permalink to &quot;NRP integration (2026-05-08)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Status</th></tr></thead><tbody><tr><td>Domain → static routing</td><td>✅</td></tr><tr><td>Domain → proxy routing</td><td>✅</td></tr><tr><td>Hot-reload via Lua timer</td><td>✅</td></tr><tr><td>Node landing page (main-server/index.html)</td><td>✅</td></tr><tr><td><code>netget reload</code> CLI (no nginx in PATH needed)</td><td>✅</td></tr><tr><td><code>netget generate-domain-map</code></td><td>✅</td></tr><tr><td>SSL via Let&#39;s Encrypt</td><td>✅</td></tr><tr><td>Dynamic SSL per domain (Lua)</td><td>✅</td></tr><tr><td>Monad mesh routing (<code>.mesh/monads</code>)</td><td>🔲 planned</td></tr><tr><td><code>netget://device/monad</code> resolution</td><td>🔲 planned</td></tr></tbody></table>`,15)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
